mapper.update:
UPDATE t_file_storage_instance
SET endpoint = #{target.endpoint}, region = #{target.region}, path_style_access = #{target.pathStyleAccess},
    trusted_certificate_pem = #{target.trustedCertificatePem}, connect_timeout_ms = #{target.connectTimeoutMs},
    read_timeout_ms = #{target.readTimeoutMs}, version = version + 1, update_time = #{now}
WHERE instance_id = #{row.instanceId} AND version = #{row.version}

UPDATE t_file_storage_instance
SET credential_mode = #{mode}, credential_vault_token = #{token}, credential_update_time = #{now},
    version = version + 1, update_time = #{now}
WHERE instance_id = #{row.instanceId} AND version = #{row.version}

UPDATE t_file_storage_instance
SET status = #{status}, version = version + 1, update_time = #{now}
WHERE instance_id = #{row.instanceId} AND version = #{row.version} AND status = #{row.status}
